function removeExplanation(str) {
  // Remove all parentheses and their contents
  str = str.replace(/\s*\([^)]*\)/g, "");
  // Remove commas
  return str.replace(/,/g, "").trim().toLowerCase();
}

function applyPhraseRules(str) {
  for (const [phrase, replacement] of Object.entries(phraseRules)) {
    const regex = new RegExp(`\\b${phrase}\\b`, "gi");
    str = str.replace(regex, replacement);
  }
  return str;
}

function applyWordRules(str) {
  return str
    .split(/\s+/)
    .map((word) =>
      phraseReplacements.has(word)
        ? word
        : wordRules.hasOwnProperty(word)
        ? wordRules[word]
        : ""
    )
    .filter(Boolean)
    .join("");
}

function shorten(input) {
  const cleaned = removeExplanation(input);
  const phraseReplaced = applyPhraseRules(cleaned);
  return applyWordRules(phraseReplaced);
}

function getEurostatFormatCurrentTime() {
  const date = new Date();

  const pad = (num) => String(num).padStart(2, "0");

  const yyyy = date.getFullYear();
  const mm = pad(date.getMonth() + 1);
  const dd = pad(date.getDate());
  const hh = pad(date.getHours());
  const min = pad(date.getMinutes());
  const ss = pad(date.getSeconds());

  // Get timezone offset in minutes and convert to ±HHMM
  const tzOffset = -date.getTimezoneOffset(); // invert sign
  const tzSign = tzOffset >= 0 ? "+" : "-";
  const tzHours = pad(Math.floor(Math.abs(tzOffset) / 60));
  const tzMinutes = pad(Math.abs(tzOffset) % 60);

  const tzString = `${tzSign}${tzHours}${tzMinutes}`;

  return `${yyyy}-${mm}-${dd}T${hh}:${min}:${ss}${tzString}`;
}

const VALID_TIME_MATCH_LEVELS = [
  "none", // does not attempt time matching
  "strict", // only matches exact string
  "smart", // matches approximate terms, e.g. 2023-04 = 2023 = 2023-Q1 = 2023-S1
];

let state = {
  datasets: {}, // Global object to store all datasets
  metadata: {}, // Global object to store all metadata
  filteredData: [], // Current filtered dataset
  selectedDataset: null, // Current metadata
  chartedCountries: new Set(), // Stores selected countries for line chart
  currentSelected: null, // Currently selected country geocode for bar chart
  timeColorCache: {}, // Cache for time-based valuesByGeo
};

let timeMatchLevel = "none"; // Default value

Object.defineProperty(state, "timeMatchLevel", {
  get() {
    return timeMatchLevel;
  },
  set(value) {
    if (!VALID_TIME_MATCH_LEVELS.includes(value)) {
      console.warn(
        `Invalid timeMatchLevel: ${value}. Possible values: [${VALID_TIME_MATCH_LEVELS.join(", ")}]`
      );
      return false; // Prevent assignment
    }
    timeMatchLevel = value;
  },
  enumerable: true,
  configurable: true,
});

