function fetchMetadata() {
  state.metadata = {};

  for (let file of metadata2.files) {
    if (file._status?.data?.status !== "success") continue;
    state.metadata[file.code] = file;
    // directly assign dataset if available
    if (file.dataset) {
      state.datasets[file.code] = file.dataset;
    }
  }

  const datasetKeys = Object.keys(state.metadata);
  setupControls(datasetKeys, "init");
}


 function handleMapPathClick(event, d) {
  const geoCode = d.properties.CNTR_ID;

  if (event.shiftKey) {
    if (
      window.eurovault.state.chartedCountries.has(geoCode) &&
      window.eurovault.state.chartedCountries.size > 1
    ) {
      window.eurovault.state.chartedCountries.delete(geoCode);
    } else if (window.eurovault.state.chartedCountries.size < 10){
      window.eurovault.state.chartedCountries.add(geoCode);
    }

    if (
      window.eurovault.chartContainer.attr("data-chart-type") !== "line" &&
      window.eurovault.state.currentSelected &&
      !window.eurovault.state.chartedCountries.has(window.eurovault.state.currentSelected)
    ) {
      window.eurovault.state.chartedCountries.add(window.eurovault.state.currentSelected);
    }

    if (window.eurovault.state.chartedCountries.size > 0) {
      showLineChart(Array.from(window.eurovault.state.chartedCountries));
    } else {
      window.eurovault.chartContainer.html("");
    }
  } else {
    // Normal click reset chartedCountries
    window.eurovault.state.chartedCountries.clear();
    window.eurovault.state.currentSelected = geoCode;
    showCountryChart(geoCode);
  }
}

 function showCountryChart(geoCode) {
  window.eurovault.chartContainer.html("").attr("data-chart-type", "bar"); // Clear previous chart
  window.eurovault.controlsTooltip.classed("hidden", true);
  
  const countryName = window.eurovault.europe.features.find(
    (f) => f.properties.CNTR_ID === geoCode
  ).properties.NAME_ENGL;

  const svg = window.eurovault.chartContainer
    .append("svg")
    .attr("id", "chart-svg")
    .attr("width", "100%")
    .attr("height", "100%");

  // Add close button
  window.eurovault.chartContainer
    .append("button")
    .text("X")
    .classed("chart-close-button", true)
    .on("click", () => {
      window.eurovault.state.currentSelected = null;
      window.eurovault.state.chartedCountries.clear();
      // Remove chart
      window.eurovault.chartContainer.html("").attr("data-chart-type", "");
      window.eurovault.controlsTooltip.classed("hidden", false);
    });

  // Filter the historical data
  const countryData = window.eurovault.state.filteredData
    .filter((d) => d.GEO === geoCode && !isNaN(+d.VALUE))
    .sort((a, b) => compareTimes(a.TIME, b.TIME));

  const chartContainerBoundingRect = window.eurovault.chartContainer
    .node()
    .getBoundingClientRect();
  const width = chartContainerBoundingRect.width;
  const height = chartContainerBoundingRect.height;
  const margin = { top: 50, right: 30, bottom: 80, left: 60 };

  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;

  const g = svg
    .append("g")
    .attr("transform", `translate(${margin.left},${margin.top})`);

  const times = countryData.map((d) => d.TIME);

  if (times.length === 1 && times[0]) {
    // If there is only one time, the chart looks stretched
    // So we add padding time values
    const time = parseTime(times[0]);
    times.unshift(time.suffix ? (time.year - 1) + "-" + time.suffix : "" + (time.year - 1));
    times.push(time.suffix ? (time.year + 1) + "-" + time.suffix : "" + (time.year + 1));
  }

  // Scales
  const x = d3
    .scaleBand()
    .domain(times)
    .range([0, plotWidth])
    .padding(0.1);

  const y = d3
    .scaleLinear()
    .domain([
      d3.min(countryData, (d) => +d.VALUE) || 0,
      d3.max(countryData, (d) => +d.VALUE) || 1,
    ])
    .nice()
    .range([plotHeight, 0]);

  const every = Math.ceil(x.domain().length / 10);
  // Axes
  g.append("g")
    .attr("transform", `translate(0,${plotHeight})`)
    .call(
      d3.axisBottom(x).tickValues(x.domain().filter((_, i) => i % every == 0))
    )
    .selectAll("text")
    .attr("transform", "rotate(-45)")
    .style("text-anchor", "end");

  g.append("g").call(d3.axisLeft(y));

  // Axis labels
  g.append("text")
    .attr("x", plotWidth / 2)
    .attr("y", plotHeight + 60)
    .attr("text-anchor", "middle")
    .attr("fill", "black")
    .text(window.eurovault.state.xlabel || "Year");

  g.append("text")
    .attr("transform", "rotate(-90)")
    .attr("x", -plotHeight / 2)
    .attr("y", -45)
    .attr("text-anchor", "middle")
    .attr("fill", "black")
    .text(window.eurovault.state.ylabel || "Value");

  // Chart title
  let title = `${countryName} - ${
    window.eurovault.state.metadata[window.eurovault.state.selectedDataset]?.label || ""
  }`;
  if (title.length > 40) {
    title = title.slice(0, 40) + "...";
  }
  svg
    .append("text")
    .attr("x", width / 2)
    .attr("y", 30)
    .attr("text-anchor", "middle")
    .style("font-size", "1.1rem")
    .style("font-weight", "bold")
    .text(title);

  // Bars
  const bars = g
    .selectAll(".bar")
    .data(countryData)
    .enter()
    .append("rect")
    .attr("class", "bar")
    .attr("x", (d) => x(d.TIME))
    .attr("y", (d) => y(+d.VALUE))
    .attr("width", x.bandwidth())
    .attr("height", (d) => plotHeight - y(+d.VALUE))
    .attr("fill", "#4682b4");

  // Tooltip
  const tooltip = d3.select("#chart-tooltip").style("opacity", 0);

  const topOffset = chartContainerBoundingRect.top;
  const leftOffset = chartContainerBoundingRect.left;

  bars
    .on("mouseover", function (event, d) {
      d3.select(this).attr("fill", d3.color("#4682b4").darker(1));
      const bar = d3.select(event.currentTarget);
      // console.log(bar.attr("x"), bar.attr("y"));
      const xPos = +bar.attr("x") + x.bandwidth() / 2;
      const yPos = +bar.attr("y");

      tooltip.transition().duration(200).style("opacity", 0.95);
      tooltip.text(`${d.TIME}: ${d.VALUE}`);

      // Position tooltip centered above the bar
      tooltip
        .style(
          "left",
          leftOffset +
            margin.left +
            xPos -
            tooltip.node().offsetWidth / 2 +
            "px"
        )
        .style("top", topOffset + margin.top + yPos - 30 + "px"); // 30px above bar
    })
    .on("mouseout", function () {
      d3.select(this).attr("fill", "#4682b4");
      tooltip.transition().duration(300).style("opacity", 0);
    });
}

 function showLineChart(countries) {
  window.eurovault.chartContainer.html("").attr("data-chart-type", "line"); // Clear previous chart
  window.eurovault.controlsTooltip.classed("hidden", true);

  const svg = window.eurovault.chartContainer
    .append("svg")
    .attr("width", "100%")
    .attr("height", "100%");

  window.eurovault.chartContainer
    .append("button")
    .text("X")
    .classed("chart-close-button", true)
    .on("click", () => {
      window.eurovault.state.currentSelected = null;
      window.eurovault.state.chartedCountries.clear();
      window.eurovault.chartContainer.html("").attr("data-chart-type", "");
      window.eurovault.controlsTooltip.classed("hidden", false);
    });

  const chartContainerBoundingRect = window.eurovault.chartContainer
    .node()
    .getBoundingClientRect();
  const width = chartContainerBoundingRect.width;
  const height = chartContainerBoundingRect.height;
  const margin = { top: 50, right: 150, bottom: 80, left: 60 };

  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;

  const g = svg
    .append("g")
    .attr("transform", `translate(${margin.left},${margin.top})`);

  // Build time domain and country data
  let allTimes = new Set();
  let countrySeries = [];

  countries.forEach((geo) => {
    const rows = window.eurovault.state.filteredData
      .filter((d) => d.GEO === geo && !isNaN(+d.VALUE))
      .map((d) => ({ time: d.TIME, value: +d.VALUE }))
      .sort((a, b) => compareTimes(a.time, b.time));

    rows.forEach((r) => allTimes.add(r.time));

    countrySeries.push({
      geo,
      name: window.eurovault.europe.features.find((f) => f.properties.CNTR_ID === geo)
        .properties.NAME_ENGL,
      values: rows,
    });
  });

  const times = Array.from(allTimes).sort(compareTimes);

  if (times.length === 1 && times[0]) {
    // If there is only one time, the chart looks stretched
    // So we add padding time values
    const time = parseTime(times[0]);
    times.unshift(time.suffix ? (time.year - 1) + "-" + time.suffix : "" + (time.year - 1));
    times.push(time.suffix ? (time.year + 1) + "-" + time.suffix : "" + (time.year + 1));
  }

  // Scales
  const x = d3.scalePoint().domain(times).range([0, plotWidth]).padding(0.1);

  const y = d3
    .scaleLinear()
    .domain([
      d3.min(countrySeries, (c) => d3.min(c.values, (d) => d.value)) || 0,
      d3.max(countrySeries, (c) => d3.max(c.values, (d) => d.value)) || 1,
    ])
    .nice()
    .range([plotHeight, 0]);

  const color = d3.scaleOrdinal().domain(countries).range(d3.schemeCategory10);

  const every = Math.ceil(x.domain().length / 10);
  // Axes
  g.append("g")
    .attr("transform", `translate(0,${plotHeight})`)
    .call(
      d3.axisBottom(x).tickValues(x.domain().filter((_, i) => i % every === 0))
    )
    .selectAll("text")
    .attr("transform", "rotate(-45)")
    .style("text-anchor", "end");

  g.append("g")
    .attr("class", "y-axis")
    .call(d3.axisLeft(y));

  // Axis labels
  g.append("text")
    .attr("x", plotWidth / 2)
    .attr("y", plotHeight + 60)
    .attr("text-anchor", "middle")
    .attr("fill", "black")
    .text(window.eurovault.state.xlabel || "Year");

  g.append("text")
    .attr("transform", "rotate(-90)")
    .attr("x", -plotHeight / 2)
    .attr("y", -45)
    .attr("text-anchor", "middle")
    .attr("fill", "black")
    .text(window.eurovault.state.ylabel || "Value");

  // Chart title
  let title = `${window.eurovault.state.metadata[window.eurovault.state.selectedDataset]?.label || ""}`;
  if (title.length > 40) {
    title = title.slice(0, 40) + "...";
  }
  svg
    .append("text")
    .attr("x", width / 2)
    .attr("y", 30)
    .attr("text-anchor", "middle")
    .style("font-size", "1.1rem")
    .style("font-weight", "bold")
    .text(title);

  // Lines
  const line = d3
    .line()
    .x((d) => x(d.time))
    .y((d) => y(d.value));

  g.selectAll(".line")
    .data(countrySeries)
    .enter()
    .append("path")
    .attr("data-country", (d) => d.geo)
    .attr("fill", "none")
    .attr("stroke", (d) => color(d.geo))
    .attr("stroke-width", 2)
    .attr("d", (d) => line(d.values));

  const tooltip = d3.select("#chart-tooltip").style("opacity", 0);

  const leftOffset = chartContainerBoundingRect.left;
  const topOffset = chartContainerBoundingRect.top;

  // Add circles to each data point
  countrySeries.forEach((series) => {
    g.selectAll(`.circle-${series.geo}`)
      .data(series.values)
      .enter()
      .append("circle")
      .attr("data-country", series.geo)
      .attr("cx", (d) => x(d.time))
      .attr("cy", (d) => y(d.value))

      .attr("r", 4)
      .attr("fill", color(series.geo))
      .attr("stroke", "#fff")
      .attr("stroke-width", 1)
      .on("mouseover", function (event, d) {
        tooltip.text(`${series.name} (${d.time}): ${d.value}`);

        const bar = d3.select(event.currentTarget);
        const xPos = +bar.attr("cx") + x.bandwidth() / 2;
        const yPos = +bar.attr("cy");

        tooltip.transition().duration(200).style("opacity", 0.95);

        // Position tooltip centered above the bar
        tooltip
          .style(
            "left",
            leftOffset +
              margin.left +
              xPos -
              tooltip.node().offsetWidth / 2 +
              "px"
          )
          .style("top", topOffset + margin.top + yPos - 30 + "px");
      })
      .on("mouseout", function () {
        tooltip.transition().duration(200).style("opacity", 0);
      });
  });

  let visibleCountries = new Set(countrySeries.map((d) => d.geo));

  function updateYScale() {
    const visibleSeries = countrySeries.filter((d) =>
      visibleCountries.has(d.geo)
    );

    const newYDomain = [
      d3.min(visibleSeries, (c) => d3.min(c.values, (d) => d.value)) || 0,
      d3.max(visibleSeries, (c) => d3.max(c.values, (d) => d.value)) || 1,
    ];

    y.domain(newYDomain).nice();

    g.select(".y-axis")
      .transition()
      .duration(500)
      .call(d3.axisLeft(y));

    g.selectAll("path[data-country]")
      .transition()
      .duration(500)
      .attr("d", (d) => line(d.values))
      .style("display", (d) => (visibleCountries.has(d.geo) ? null : "none"));

    g.selectAll("circle[data-country]")
      .transition()
      .duration(500)
      .attr("cy", (d) => y(d.value))
      .style("display", function () {
        const geo = d3.select(this).attr("data-country");
        return visibleCountries.has(geo) ? null : "none";
      });
  }

  const legend = svg
    .append("g")
    .attr(
      "transform",
      `translate(${plotWidth + margin.left + 20}, ${margin.top})`
    );

  countrySeries.forEach((d, i) => {
    const group = legend
      .append("g")
      .attr("transform", `translate(0, ${i * 20})`)
      .style("cursor", "pointer")
      .attr("data-country", d.geo);
    group
      .append("rect")
      .attr("width", 12)
      .attr("height", 12)
      .attr("fill", color(d.geo));
    group
      .append("text")
      .attr("x", 16)
      .attr("y", 10)
      .text(d.name)
      .style("font-size", "12px")
      .classed("noselect", true);

    group.on("click", function (e) {
      const elem = d3.select(this);
      const geoCode = elem.attr("data-country");

      const isHidden = elem.classed("strike");
      elem.classed("strike", !isHidden);

      if (isHidden) {
        visibleCountries.add(geoCode);
      } else {
        visibleCountries.delete(geoCode);
      }

      window.eurovault.chartContainer
        .selectAll(`path[data-country='${geoCode}']`)
        .classed("hidden", !visibleCountries.has(geoCode));
        // .style("display", visibleCountries.has(geoCode) ? null : "none");

      window.eurovault.chartContainer
        .selectAll(`circle[data-country='${geoCode}']`)
        .classed("hidden", !visibleCountries.has(geoCode));
        // .style("display", visibleCountries.has(geoCode) ? null : "none");

      updateYScale();
    });
  });
}

 function setupControls(datasetKeys, updateSource = null) {
  const datasetSelect = document.getElementById("dataset-select");
  const filterPanel = document.getElementById("filter-panel");

  // Populate dataset dropdown
  datasetKeys.forEach((key, index) => {
    const option = document.createElement("option");
    option.value = key;
    option.textContent = window.eurovault.state.metadata[key].label;
    datasetSelect.appendChild(option);
  });

  datasetSelect.value = datasetKeys[0];
  updateFilters(datasetKeys[0], updateSource);

  datasetSelect.addEventListener("change", (e) => {
    for (const key in window.eurovault.state.timeColorCache) {
      delete window.eurovault.state.timeColorCache[key];
    }
    const slider = document.querySelector(
      "#time-slider-container input[type=range]"
    );
    const selectedTime = slider ? window.eurovault.state.times[+slider.value] : null;
    const selectedKey = e.target.value;

  // If already loaded, just update filters
  if (window.eurovault.state.datasets[selectedKey]) {
    updateFilters(selectedKey, "dataset", selectedTime);
  } else {
    // Load new CSV
    d3.csv(`/data/files/${selectedKey}.csv`)
      .then((csv) => {
        // Clear old dataset(s)
        for (const key in window.eurovault.state.datasets) {
          delete window.eurovault.state.datasets[key];
        }

        window.eurovault.state.datasets[selectedKey] = csv;

        updateFilters(selectedKey, "dataset", selectedTime);
      })
      .catch((error) => {
        console.error(`Error loading CSV for ${selectedKey}:`, error);
      });
  }
  });

  // edit-metadata-button
  // document.getElementById("edit-metadata-button").onclick = (event) => {
  //   if (!localStorage) {
  //     return;
  //   }
  //   localStorage.removeItem("selectedTables");
  //   localStorage.setItem("step", 1);
  //   window.location.href = "/metadata";
  // };

  function updateFilters(dataset, updateSource = null, selectedTime = null) {
    const groupsToRemove = filterPanel.querySelectorAll(".control-group");

    groupsToRemove.forEach((group) => {
      filterPanel.removeChild(group);
    });

    window.eurovault.state.selectedDataset = dataset;

    // const values = window.eurovault.state.metadata[window.eurovault.state.selectedDataset].values || {};
    const values = window.eurovault.state.metadata[window.eurovault.state.selectedDataset].dimensionPrefs || {};

    // Create dropdowns for each param
    Object.keys(values).forEach((param) => {
      if (param === "time") {
        return;
      }
      const groupDiv = document.createElement("div");
      groupDiv.classList.add("control-group");

      const label = document.createElement("label");
      label.textContent = values[param].label;
      label.htmlFor = `filter-${param}`;

      const select = document.createElement("select");
      select.id = `filter-${param}`;

      const options = Object.keys(values[param].category.label);
      options.forEach((opt) => {
        const option = document.createElement("option");
        option.value = opt;
        option.textContent = values[param].category.label[opt];
        select.appendChild(option);
      });

      select.value = options[0];

      // Add change event
      select.addEventListener("change", () => {
        for (const key in window.eurovault.state.timeColorCache) {
          delete window.eurovault.state.timeColorCache[key];
        }
        const slider = document.querySelector(
          "#time-slider-container input[type=range]"
        );
        const selectedTime = slider ? window.eurovault.state.times[+slider.value] : null;

        filterData(window.eurovault.state.selectedDataset, "filter", selectedTime);
      });

      groupDiv.appendChild(label);
      groupDiv.appendChild(select);

      if (options.length <= 1) {
        select.disabled = true;
        filterPanel.append(groupDiv);
      } else {
        filterPanel.prepend(groupDiv);
      }
    });

    // Initial filtering
    filterData(window.eurovault.state.selectedDataset, updateSource, selectedTime);
  }
}

function filterData(selectedDataset, updateSource = null, selectedTime = null) {
  let data = window.eurovault.state.datasets[selectedDataset];

  // const values = window.eurovault.state.metadata[window.eurovault.state.selectedDataset].values || {};
  const values = window.eurovault.state.metadata[window.eurovault.state.selectedDataset].dimensionPrefs || {};
  let filters = {};

  // Gather selected filters
  Object.keys(values).forEach((param) => {
    // store unit of measure
    if (param === "unit") {
      const selected = document.getElementById(`filter-${param}`).value;
      window.eurovault.state.ylabel = values.unit.category.label[selected];
    }

    // store unit of time
    if (param === "time") {
      // Take any element from the time category, as they share the same structure
      const selected = Object.keys(values.time.category.label)[0];
      if (selected.indexOf("Q") !== -1) {
        window.eurovault.state.xlabel = "Quarter";
        return;
      } else if (selected.indexOf("S") !== -1) {
        window.eurovault.state.xlabel = "Season";
        return;
      } else if (selected.indexOf("-") !== -1) {
        window.eurovault.state.xlabel = "Month";
        return;
      }
      window.eurovault.state.xlabel = "Year";
      return;
    }

    // Ignore filters with one option
    if (Object.keys(values[param].category.index).length === 1) {
      return;
    }

    const selected = document.getElementById(`filter-${param}`).value;
    filters[param.toUpperCase()] = selected; // CSV uses uppercase column names
  });

  // Filter the dataset
  window.eurovault.state.filteredData = data.filter((row) => {
    return Object.keys(filters).every((param) => {
      return row[param] === filters[param];
    });
  });

  // console.log(`Filtered dataset for ${selectedDataset}:`, filteredData);
  updateMapColors(updateSource, selectedTime);

  if (window.innerWidth <= 768) {
    return;
  }

  const chartType = window.eurovault.chartContainer.attr("data-chart-type");
  if (chartType) {
    if (chartType == "bar") {
      const geoCode = window.eurovault.state.currentSelected;
      if (geoCode) {
        showCountryChart(geoCode);
      }
    } else if (chartType == "line") {
      showLineChart(Array.from(window.eurovault.state.chartedCountries));
    }
  }
}

function findClosestTimeMatch(selectedTime, availableTimes, timeMatchLevel) {
  if (!selectedTime || !availableTimes || availableTimes.length === 0)
    return null;

  // 1. Exact match
  if (availableTimes.includes(selectedTime)) return selectedTime;

  if (timeMatchLevel === "strict") return null;

  // 2. Extract year
  const yearMatch = selectedTime.match(/^\d{4}/);
  const year = yearMatch ? yearMatch[0] : null;

  if (year) {
    const sameYearMatches = availableTimes.filter((t) => t.startsWith(year));
    if (sameYearMatches.length > 0) {
      return sameYearMatches[0]; // return first match in same year
    }
  }

  // 3. Start with selectedTime (e.g., "2023" matches "2023-Q2")
  const prefixMatches = availableTimes.filter((t) =>
    t.startsWith(selectedTime)
  );
  if (prefixMatches.length > 0) return prefixMatches[0];

  // 4. End with selectedTime (e.g., "Q2" matches "2023-Q2")
  const suffixMatches = availableTimes.filter((t) => t.endsWith(selectedTime));
  if (suffixMatches.length > 0) return suffixMatches[0];

  // 5. Loose fuzzy match
  const looseMatches = availableTimes.filter((t) => t.includes(selectedTime));
  if (looseMatches.length > 0) return looseMatches[0];

  return null;
}

function updateMapColors(updateSource = null, selectedTime = null) {
  if (!["dataset", "filter", "timeSlider", "external", "init"].includes(updateSource)) {
    throw new Error(`Unknown update source: ${updateSource}`);
  }

  const timeMatchLevel = window.eurovault.state.timeMatchLevel;

  // console.log("updateSource", updateSource);

  let times = [...new Set(window.eurovault.state.filteredData.map((d) => d.TIME))];
  times.sort(compareTimes);
  window.eurovault.state.times = times;

  // Update the time to be selected based on updateSource and timeMatchLevel
  let matchedTime = null;

  if (timeMatchLevel === "none" && ["dataset", "filter"].includes(updateSource)) {
      selectedTime = null;
  } else {
    matchedTime = findClosestTimeMatch(selectedTime, times, timeMatchLevel);
  }

  // Find closest time to match with, or default with the latest time
  selectedTime = matchedTime || times[times.length - 1];

  let valuesByGeo = window.eurovault.state.timeColorCache[selectedTime];
  if (!valuesByGeo) {
    valuesByGeo = {};
    window.eurovault.state.filteredData.forEach((row) => {
      const geo = row.GEO;
      if (!geo) return;
      if (row.TIME === selectedTime) {
        const val = parseFloat(row.VALUE);
        valuesByGeo[geo] = val;
      }
    });
    window.eurovault.state.timeColorCache[selectedTime] = valuesByGeo;
  }

  // 4. Compute min/max ignoring zeros
  const nonZeroValues = Object.values(valuesByGeo).filter((v) => v > 0);
  const scale = d3.scaleQuantile().domain(nonZeroValues).range(window.eurovault.colorPalette);

  // 5. Re-color the countries
  window.eurovault.mapContainer
    .selectAll("path")
    .transition()
    .duration(200)
    .attr("fill", function (d) {
      if (!d || !d.properties) {
        console.error(d, this);
        return;
      }
      const geoCode = d.properties.CNTR_ID;
      const val = valuesByGeo[geoCode] ?? 0;

      if (val === 0 || isNaN(val)) return "#cccccc"; // Grey for 0/missing
      return scale(val);
    });

  window.eurovault.mapContainer
    .selectAll("path")
    .on("mouseover", function (event, d) {
      d3.select(this).raise().style("stroke-width", 0.5);
      const geoCode = d.properties.CNTR_ID;
      const countryName = d.properties.NAME_ENGL;
      const val = valuesByGeo[geoCode] ?? 0;

      const tooltip = d3.select("#map-tooltip");
      tooltip
        .style("display", "block")
        .html(`<strong>${countryName}</strong><br/>Value: ${val || "0"}`);
    })
    .on("touchstart", function (event, d) {
      d3.select(this).raise().style("stroke-width", 0.5);
      const geoCode = d.properties.CNTR_ID;
      const countryName = d.properties.NAME_ENGL;
      const val = valuesByGeo[geoCode] ?? 0;

      const tooltip = d3.select("#map-tooltip");
      tooltip
        .style("display", "block")
        .html(`<strong>${countryName}</strong><br/>Value: ${val || "0"}`);
    })
    .on("mousemove", function (event) {
      d3.select("#map-tooltip")
        .style("left", event.pageX + "px")
        .style("top", event.pageY - 40 + "px");
    })
    .on("mouseout", function () {
      d3.select(this).style("stroke-width", 0.25);
      d3.select("#map-tooltip").style("display", "none");
    });

  // 6. Update info panel
  const dataset = document.getElementById("dataset-select").value;
  const meta = window.eurovault.state.metadata[dataset];
  const label = meta.label || dataset;
  const description = meta.description || "";

  // Set title and label
  d3.select("#info-label").text(label);

  // Handle description panel
  const descPanel = d3.select("#info-description");
  descPanel.html(""); // Clear old
  descPanel.classed("hidden", true); // Hide by default
  const helpIcon = d3.select("#info-help");

  if (description) {
    descPanel.text(description);

    helpIcon
      .on("mouseenter", () => descPanel.classed("hidden", false))
      .on("mouseleave", () => descPanel.classed("hidden", true))
      .classed("hidden", false)
      .classed("inline-block", true);
  } else {
    helpIcon.classed("hidden", true).classed("inline-block", false);
  }

  // 7. Update color legend
  const legend = d3.select("#color-legend").html("");

  if(!window.eurovault.state.filteredData.length) {
    // No reason to display data-specific information
    // When there is no data
    return;
  }

  const thresholds = scale.quantiles();
  const unit = shorten(window.eurovault.state.ylabel) || "";

  const allThresholds = [
    d3.min(nonZeroValues),
    ...thresholds,
    d3.max(nonZeroValues),
  ];

  allThresholds.forEach((val, i) => {
    if (i === allThresholds.length - 1) return; // Skip last point (no range to next)

    const from = allThresholds[i];
    const to = allThresholds[i + 1];
    const color = window.eurovault.colorPalette[i];
    const label =
      from.toFixed(0) === to.toFixed(0)
        ? `${from.toFixed(2)}-${to.toFixed(2)}`
        : `${from.toFixed(0)}-${to.toFixed(0)}`;

    legend
      .append("div")
      .style("display", "flex")
      .style("align-items", "center")
      .style("margin-bottom", "2px").html(`
      <div style="width: 18px; height: 14px; background:${color}; margin-right:6px;"></div>
      <div>${unit ? `${label} ${unit}` : label}</div>
    `);
  });

  // Add grey color for zero/missing
  legend
    .append("div")
    .style("display", "flex")
    .style("align-items", "center")
    .style("margin-top", "6px")
    .html(
      `<div style="width: 18px; height: 14px; background:#cccccc; margin-right:6px;"></div><div>No data / 0</div>`
    );

  // Update Time Slider
  if (updateSource === "timeSlider") {
    d3.select("#slider-text-div").text(`Showing data for: ${selectedTime}`);
    return;
  }

  let sliderContainer = d3.select("#time-slider-container");
  sliderContainer.html(""); // Clear existing content

  if (times.length > 1) {
    const selectedIndex = times.indexOf(selectedTime);

    sliderContainer
      .append("input")
      .attr("type", "range")
      .attr("min", 0)
      .attr("max", times.length - 1)
      .attr("value", selectedIndex)
      .style("width", "100%")
      .on("input", function () {
        const index = +this.value;
        const newTime = times[index];
        updateMapColors("timeSlider", newTime);
      });

    sliderContainer
      .append("div")
      .attr("id", "slider-text-div")
      .style("text-align", "center")
      .style("font-size", "0.8rem")
      .style("margin-top", "4px")
      .text(`Showing data for: ${selectedTime}`);
  }
}

// Handle resize

window.addEventListener("resize", () => {
  resizeMap();

  const svg = d3.select("#map-svg");

  if (window.innerWidth <= 768) {
    svg.selectAll("path").on("click", null);
    return;
  }

  svg.selectAll("path").on("click", handleMapPathClick);

  const chartType = window.eurovault.chartContainer.attr("data-chart-type");
  if (chartType) {
    if (chartType == "bar") {
      const geoCode = window.eurovault.state.currentSelected;
      if (geoCode) {
        showCountryChart(geoCode);
      }
    } else if (chartType == "line") {
      showLineChart(Array.from(window.eurovault.state.chartedCountries));
    }
  }
});
